"""Editable, topic-specific lecture guides. Existing detailed protocols follow.

Each page has a concrete aim, algorithm/variables, notebook action and reading
task. Numerical research evidence remains in the original retained sections.
"""

GUIDES = {}

def page(title, paragraphs, equations=(), figure=None, caption=None):
    return dict(title=title, paragraphs=paragraphs, equations=list(equations), figure=figure, caption=caption)

